ids=['lem-arith-rigidified-line-bundle-descent','lem-arith-hilbert-divisor-charts-and-picard-diagonal','lem-arith-picard-representation-by-generic-quotient-and-translates','lem-arith-coherent-kunneth-and-proper-image-dual','lem-arith-dual-and-poincare-bundle-finite-field-descent','lem-arith-homogeneous-bundle-vanishing-and-mumford-surjectivity','lem-arith-finite-cartier-duality-and-exactness','lem-arith-dual-isogeny-kernel-and-abelian-biduality','lem-arith-theta-extension-splitting-and-isotropic-descent','lem-arith-symmetric-homomorphism-is-a-mumford-map','lem-arith-polarization-and-picard-twist-ampleness','lem-arith-poincare-cohomology-at-the-identity','lem-arith-mumford-map-degree-is-euler-characteristic-square']
